insert into games (id, data) values ('game-word-quest', $j${"id":"game-word-quest","title":"Word Quest","slug":"word-quest","kind":"embed","summary":"An arcade word search: beat the clock and circle the hidden words, K to 5th grade.","players":"1","minutes":5,"ageMin":5,"ageMax":11,"rules":["Pick your grade, from Kindergarten to 5th. Older grades get bigger boards, longer words and words that run in more directions.","Pick Arcade to race the clock, or Chill to play with no clock.","Press the first letter of a word, slide to the last letter, and let go to circle it. You can also tap the first letter, then the last one.","Tap a word in the list to hear it read out loud.","In Arcade, every word adds time to the clock, and words found quickly build a combo for more points.","Look out for secret words: they are not on the list, and they are worth bonus points.","Stuck? Press Hint and the first letter of a word bounces.","Clear the board for 1 to 3 stars and a new round. Your best Arcade score is kept on this device.","Sound is on: press the speaker button to turn it off."],"leadsTo":"act-story-cubes","interactive":true,"path":"games/word-quest.html","icon":"text-search","p1":"#D8C8F5","p2":"#4B2A85","status":"published","featured":true,"createdAt":"2026-11-07T23:10:00.000Z","updatedAt":"2026-11-07T23:10:00.000Z","badge":"New","order":0,"cover":{"src":"assets/games/word-quest.jpg","alt":"A Word Quest board: MOUSE, PLANT and MUSIC circled in blue, green and pink, ROBOT being circled across the letters, the word list with three ticks, a combo of x3 and Chike saying Nice one!"},"vocabWord":"vocabulary","vocabSay":"voh-KAB-yuh-lair-ee · noun","vocabMeaning":"All the words you know and understand.","vocabExample":"In Word Quest, tap a word to hear it. Every word you find and say grows your vocabulary!"}$j$::jsonb)
